 * Only properties defined in the sourceInterfaceClazz interface are merged.
 * 
 * @param <I> the interface type
 * @param <S> the source type that extends the interface
 * @param <T> the target type that extends the interface
 * @param source the source bean to copy values from
 * @param target the target bean to copy values to
 * @param sourceInterfaceClazz the interface class defining which properties to merge
 * @param overrideNonNullOnly if true, only override target properties with non-null source values
 * @param overrideNonNullTargetValues if false, skip copying if target property is already non-null; if true, allow overwriting non-null target values
 * @return the modified target object
 */
public static <I, S extends I, T extends I> T mergeBeans(S source, T target, Class<I> sourceInterfaceClazz,
		boolean overrideNonNullOnly, boolean overrideNonNullTargetValues) {

	Assert.notNull(source, "Source must not be null");
	Assert.notNull(target, "Target must not be null");
	Assert.notNull(sourceInterfaceClazz, "SourceInterfaceClazz must not be null");

	BeanWrapper sourceBeanWrapper = new BeanWrapperImpl(source);
	BeanWrapper targetBeanWrapper = new BeanWrapperImpl(target);

	// Get all property descriptors from the interface
	BeanWrapper interfaceBeanWrapper = new BeanWrapperImpl(sourceInterfaceClazz);
	PropertyDescriptor[] interfacePropertyDescriptors = interfaceBeanWrapper.getPropertyDescriptors();

	for (PropertyDescriptor interfacePropertyDescriptor : interfacePropertyDescriptors) {
		String propertyName = interfacePropertyDescriptor.getName();

		// Skip excluded properties
		if (BEAN_MERGE_FIELD_EXCISIONS.contains(propertyName)) {
			continue;
		}

		// Check if the property is readable in the source and writable in the target
		if (sourceBeanWrapper.isReadableProperty(propertyName)
				&& targetBeanWrapper.isWritableProperty(propertyName)) {

			Object sourceValue = sourceBeanWrapper.getPropertyValue(propertyName);

			// If overrideNonNullOnly is true, only copy non-null values
			if (overrideNonNullOnly && sourceValue == null) {
				continue;
			}

			// If overrideNonNullTargetValues is false, skip if target value is already non-null
			if (!overrideNonNullTargetValues) {
				Object targetValue = targetBeanWrapper.getPropertyValue(propertyName);
				if (targetValue != null) {
					continue;
				}
			}

			targetBeanWrapper.setPropertyValue(propertyName, sourceValue);
		}
	}

	return target;
}

